diff --git a/mail/themes/shared/mail/aboutExtra.css b/mail/themes/shared/mail/aboutExtra.css
index 8069e75e282..b4ee80056b2 100644
--- a/mail/themes/shared/mail/aboutExtra.css
+++ b/mail/themes/shared/mail/aboutExtra.css
@@ -165,14 +165,26 @@ recommended-addon-card .addon.card:hover {
   border-radius: var(--button-border-radius);
 }

-panel-item {
+panel-list {
+  --panel-list-background-color: var(--color-surface-subtle);
+  --panel-list-color: var(--color-text-base);
+  --panel-list-border-color: var(--color-surface-border-intense);
+  --panel-list-border-radius: 8px;
+  padding: 4px;
+}
+
+panel-item::part(button) {
+  border-radius: 3px;
+  background-position-x: 3px;
+  --button-background-color-hover: var(--background-color-list-item-hover);
+  --button-background-color-active: var(--background-color-list-item-hover);
+}
+
+panel-item[action="remove"]::part(button) {
+  background-image: var(--icon-trash);
   -moz-context-properties: fill, stroke;
   fill: color-mix(in srgb, currentColor 20%, transparent);
   stroke: currentColor;
-
-  &[action="remove"] {
-    --icon: var(--icon-trash);
-  }
 }

 /* Override the absolute (px) font-size values in aboutaddons.css. */
